<?php

declare(strict_types=1);

namespace Unicorn\Migration;

/**
 * Source-independent table description produced by every MigrationSourceInterface.
 *
 * Key columns may carry a prefix length, e.g. "title(150)". Key names are always generated by the schema builder.
 */
final readonly class TableDefinition
{
    /**
     * @param  list<ColumnDefinition>  $columns
     * @param  list<string>            $primary  Table-level (composite) primary key columns.
     * @param  list<list<string>>      $indexes
     * @param  list<list<string>>      $uniques
     */
    public function __construct(
        public string $name,
        public array $columns,
        public string $description = '',
        public array $primary = [],
        public array $indexes = [],
        public array $uniques = [],
    ) {
    }
}
